export class GlobalTariffEngine {
  public getTariffRule(countryCodeIso: string, hsCode: string): CountryTariffRule | undefined {
    return GLOBAL_TARIFF_DATABASE.find(r => r.countryCodeIso === countryCodeIso && r.hsTariffCode === hsCode);
  }
}
export const globalTariffEngine = new GlobalTariffEngine();
